const e=JSON.parse(`[{"id":"nl-01","title":"Checking a Patient's Name","scene":"第一次見病人：自我介紹、核對姓名和生日","level":"A2","accent":"en-US","you":"Nurse Kim","emma":"Mr. Lopez","dialogue":[{"who":"Nurse Kim","en":"Good morning. My name is Kim, and I'm your nurse today.","zh":"早安，我叫 Kim，今天由我照顧你。"},{"who":"Mr. Lopez","en":"Good morning, Kim.","zh":"早安，Kim。"},{"who":"Nurse Kim","en":"Before I start, can you tell me your full name, please?","zh":"開始之前，可以請你告訴我你的全名嗎？"},{"who":"Mr. Lopez","en":"Daniel Lopez.","zh":"Daniel Lopez。"},{"who":"Nurse Kim","en":"And what is your date of birth?","zh":"你的出生日期是？"},{"who":"Mr. Lopez","en":"March third, 1958.","zh":"1958 年 3 月 3 日。"},{"who":"Nurse Kim","en":"Thank you. That matches your wristband.","zh":"謝謝，跟你的手圈一樣。"},{"who":"Mr. Lopez","en":"Why do you ask me every time?","zh":"你們為什麼每次都要問？"},{"who":"Nurse Kim","en":"We check two things every time, so we never give the wrong medicine to the wrong person.","zh":"我們每次都核對兩樣東西，才不會把藥給錯人。"},{"who":"Mr. Lopez","en":"OK, that makes sense.","zh":"好，有道理。"},{"who":"Nurse Kim","en":"If you need anything, press this button and I'll come.","zh":"有需要就按這個按鈕，我會過來。"}],"questions":[{"q":"What two things does the nurse check?","options":["His name and room number","His name and date of birth","His phone number and address"],"answer":1},{"q":"Why does the nurse check every time?","options":["Because the computer is broken","So she doesn't give medicine to the wrong person","Because Mr. Lopez forgot his name"],"answer":1},{"q":"What should Mr. Lopez do if he needs help?","options":["Walk to the nurses' station","Call his family","Press the button"],"answer":2}],"words":[{"en":"date of birth","zh":"出生日期"},{"en":"wristband","zh":"手圈"},{"en":"match","zh":"相符"},{"en":"press","zh":"按"}]},{"id":"nl-02","title":"Allergies and Home Medicines","scene":"新病人住院：問過敏史和平常在家吃的藥","level":"A2","accent":"en-US","you":"Nurse Park","emma":"Mrs. Chen","dialogue":[{"who":"Nurse Park","en":"Mrs. Chen, I need to ask you some questions for your admission.","zh":"陳太太，住院需要問你幾個問題。"},{"who":"Mrs. Chen","en":"Sure.","zh":"好。"},{"who":"Nurse Park","en":"Are you allergic to any medicines?","zh":"你對任何藥物過敏嗎？"},{"who":"Mrs. Chen","en":"Yes, penicillin. I get a rash and my face swells.","zh":"有，盤尼西林。我會起疹子，臉會腫。"},{"who":"Nurse Park","en":"Thank you. I'll put a red allergy band on your wrist. Do you have any food allergies?","zh":"謝謝。我會在你手腕戴紅色過敏手圈。有食物過敏嗎？"},{"who":"Mrs. Chen","en":"No, just the medicine.","zh":"沒有，只有藥。"},{"who":"Nurse Park","en":"What medicines do you take at home?","zh":"你在家吃哪些藥？"},{"who":"Mrs. Chen","en":"A blood pressure pill every morning, and some vitamins.","zh":"每天早上一顆血壓藥，還有一些維他命。"},{"who":"Nurse Park","en":"Did you bring them with you?","zh":"你有帶來嗎？"},{"who":"Mrs. Chen","en":"Yes, they're in my bag.","zh":"有，在我包包裡。"},{"who":"Nurse Park","en":"Great. Please don't take them by yourself here. We will give you your medicines.","zh":"很好。在這裡請不要自己吃，我們會給你藥。"}],"questions":[{"q":"What is Mrs. Chen allergic to?","options":["Vitamins","Penicillin","Peanuts"],"answer":1},{"q":"What happens when she has an allergic reaction?","options":["She gets a headache","She can't sleep","She gets a rash and her face swells"],"answer":2},{"q":"What does the nurse ask her NOT to do?","options":["Bring her bag","Take her own medicines in the hospital","Eat hospital food"],"answer":1}],"words":[{"en":"admission","zh":"住院"},{"en":"allergic","zh":"過敏的"},{"en":"rash","zh":"疹子"},{"en":"swell","zh":"腫起來"},{"en":"allergy band","zh":"過敏手圈"}]},{"id":"nl-03","title":"Asking About Pain","scene":"病人說痛：用 0 到 10 分評估疼痛","level":"A2","accent":"en-US","you":"Nurse Lee","emma":"Mr. Brown","dialogue":[{"who":"Nurse Lee","en":"Mr. Brown, you look uncomfortable. Are you in pain?","zh":"Brown 先生，你看起來不太舒服，會痛嗎？"},{"who":"Mr. Brown","en":"Yes, my stomach hurts.","zh":"會，我肚子痛。"},{"who":"Nurse Lee","en":"On a scale from zero to ten, zero is no pain and ten is the worst pain. What number is your pain?","zh":"從 0 到 10 分，0 分是不痛，10 分是最痛，你現在幾分？"},{"who":"Mr. Brown","en":"About a seven.","zh":"大概 7 分。"},{"who":"Nurse Lee","en":"Can you show me where it hurts?","zh":"可以指給我看哪裡痛嗎？"},{"who":"Mr. Brown","en":"Right here, on the right side.","zh":"這裡，右邊。"},{"who":"Nurse Lee","en":"Is it sharp, dull, or burning?","zh":"是刺痛、悶痛，還是燒灼痛？"},{"who":"Mr. Brown","en":"Sharp. It gets worse when I move.","zh":"刺痛，動的時候更痛。"},{"who":"Nurse Lee","en":"When did it start?","zh":"什麼時候開始的？"},{"who":"Mr. Brown","en":"About two hours ago.","zh":"大概兩小時前。"},{"who":"Nurse Lee","en":"Thank you. I'll tell your doctor and come back with something for the pain.","zh":"謝謝。我會告訴醫師，再帶止痛的東西回來。"}],"questions":[{"q":"What number does Mr. Brown give his pain?","options":["Two","Seven","Ten"],"answer":1},{"q":"What kind of pain is it?","options":["Dull","Burning","Sharp"],"answer":2},{"q":"What will the nurse do next?","options":["Ask him to walk","Tell the doctor","Bring him food"],"answer":1}],"words":[{"en":"scale","zh":"量表"},{"en":"sharp","zh":"刺痛的"},{"en":"dull","zh":"悶痛的"},{"en":"burning","zh":"燒灼感的"},{"en":"worse","zh":"更糟"}]},{"id":"nl-04","title":"Checking Vital Signs","scene":"早上量生命徵象，順便說明數字","level":"A2","accent":"en-GB","you":"Nurse Taylor","emma":"Mrs. Wilson","dialogue":[{"who":"Nurse Taylor","en":"Good morning, Mrs. Wilson. I'm going to check your vital signs.","zh":"早安 Wilson 太太，我要幫你量生命徵象。"},{"who":"Mrs. Wilson","en":"What will you check?","zh":"你要量什麼？"},{"who":"Nurse Taylor","en":"Your temperature, pulse, breathing, blood pressure and oxygen level.","zh":"體溫、脈搏、呼吸、血壓和血氧。"},{"who":"Mrs. Wilson","en":"All right.","zh":"好。"},{"who":"Nurse Taylor","en":"Please hold this under your tongue. Your temperature is thirty-seven point two. That's normal.","zh":"請把這個含在舌頭下。你的體溫 37.2 度，正常。"},{"who":"Mrs. Wilson","en":"Good.","zh":"太好了。"},{"who":"Nurse Taylor","en":"Now I'll put this clip on your finger to check your oxygen. It's ninety-seven percent.","zh":"現在把這個夾在你手指上量血氧，97%。"},{"who":"Mrs. Wilson","en":"Is that good?","zh":"這樣好嗎？"},{"who":"Nurse Taylor","en":"Yes, it is. Your blood pressure is a bit high, one hundred and fifty over ninety.","zh":"很好。你的血壓有點高，150/90。"},{"who":"Mrs. Wilson","en":"Oh dear. Is that bad?","zh":"天啊，這樣不好嗎？"},{"who":"Nurse Taylor","en":"Try to relax. I'll check it again in thirty minutes and let the doctor know.","zh":"先放輕鬆，我 30 分鐘後再量一次，也會讓醫師知道。"}],"questions":[{"q":"Which number is a bit high?","options":["Her temperature","Her oxygen level","Her blood pressure"],"answer":2},{"q":"What does the nurse put on her finger?","options":["A clip to check her oxygen","A bandage","A thermometer"],"answer":0},{"q":"When will the nurse check again?","options":["Tomorrow morning","In two hours","In thirty minutes"],"answer":2}],"words":[{"en":"vital signs","zh":"生命徵象"},{"en":"temperature","zh":"體溫"},{"en":"pulse","zh":"脈搏"},{"en":"blood pressure","zh":"血壓"},{"en":"oxygen level","zh":"血氧"}]},{"id":"nl-05","title":"Preventing Falls","scene":"年長病人想自己下床：說明防跌","level":"A2","accent":"en-US","you":"Nurse Garcia","emma":"Mr. Davis","dialogue":[{"who":"Nurse Garcia","en":"Mr. Davis, are you trying to get up?","zh":"Davis 先生，你要起來嗎？"},{"who":"Mr. Davis","en":"Yes, I want to go to the bathroom.","zh":"對，我想去廁所。"},{"who":"Nurse Garcia","en":"Please wait. Your new medicine can make you dizzy.","zh":"請等一下。你的新藥可能會讓你頭暈。"},{"who":"Mr. Davis","en":"I feel fine.","zh":"我覺得還好。"},{"who":"Nurse Garcia","en":"I know, but you almost fell yesterday. Please press the call button and wait for me before you get up.","zh":"我知道，可是你昨天差點跌倒。起來之前請按呼叫鈴，等我過來。"},{"who":"Mr. Davis","en":"Every time?","zh":"每次都要嗎？"},{"who":"Nurse Garcia","en":"Every time, please. Let me help you put on these socks. They are non-slip.","zh":"每次都要，拜託。我幫你穿這雙襪子，是防滑的。"},{"who":"Mr. Davis","en":"OK.","zh":"好。"},{"who":"Nurse Garcia","en":"Sit on the edge of the bed for a moment first. Do you feel dizzy?","zh":"先在床邊坐一下。會頭暈嗎？"},{"who":"Mr. Davis","en":"A little.","zh":"有一點。"},{"who":"Nurse Garcia","en":"Then let's wait one more minute. I'll walk with you.","zh":"那我們再等一分鐘，我陪你走。"}],"questions":[{"q":"Where does Mr. Davis want to go?","options":["To the nurses' station","To the bathroom","Home"],"answer":1},{"q":"Why must he wait for the nurse?","options":["His medicine can make him dizzy","The bathroom is closed","It is lunch time"],"answer":0},{"q":"What does the nurse give him?","options":["A wheelchair","A blanket","Non-slip socks"],"answer":2}],"words":[{"en":"dizzy","zh":"頭暈的"},{"en":"call button","zh":"呼叫鈴"},{"en":"non-slip","zh":"防滑的"},{"en":"edge","zh":"邊緣"},{"en":"fall","zh":"跌倒"}]},{"id":"nl-06","title":"Giving Oral Medicine","scene":"給口服藥：核對身分、量脈搏、說明用途和副作用","level":"B1","accent":"en-US","you":"Nurse Patel","emma":"Ms. Rivera","dialogue":[{"who":"Nurse Patel","en":"Hi, Ms. Rivera. It's time for your morning medicines. Can you tell me your name and date of birth?","zh":"嗨 Rivera 小姐，該吃早上的藥了。可以告訴我你的名字和出生日期嗎？"},{"who":"Ms. Rivera","en":"Ana Rivera, July twelfth, 1975.","zh":"Ana Rivera，1975 年 7 月 12 日。"},{"who":"Nurse Patel","en":"Thank you. This small white pill is metoprolol. It's for your blood pressure and heart rate.","zh":"謝謝。這顆白色小藥丸是 metoprolol，用來控制血壓和心跳。"},{"who":"Ms. Rivera","en":"Can I take it now?","zh":"我可以現在吃嗎？"},{"who":"Nurse Patel","en":"First let me check your pulse. It's sixty-eight, so that's fine. You can take it with your breakfast.","zh":"我先量你的脈搏。68 下，可以。你可以配早餐吃。"},{"who":"Ms. Rivera","en":"Are there any side effects?","zh":"有副作用嗎？"},{"who":"Nurse Patel","en":"Some people feel tired or dizzy at first. Get up slowly, and tell me if you feel lightheaded.","zh":"有些人一開始會累或頭暈。起身要慢，覺得頭昏要告訴我。"},{"who":"Ms. Rivera","en":"And what's this other pill?","zh":"那另一顆是什麼？"},{"who":"Nurse Patel","en":"That's a stool softener. Your pain medicine can cause constipation, and this helps.","zh":"那是軟便劑。你的止痛藥會造成便祕，這個可以幫忙。"},{"who":"Ms. Rivera","en":"Oh, I see. Thank you for explaining.","zh":"喔，原來如此，謝謝你解釋。"},{"who":"Nurse Patel","en":"Of course. You can always ask me what a medicine is for.","zh":"不客氣。你隨時都可以問我藥是做什麼用的。"}],"questions":[{"q":"What does the nurse check before giving the pill?","options":["Her pulse","Her temperature","Her weight"],"answer":0},{"q":"What side effect does the nurse talk about?","options":["Feeling tired or dizzy","A rash","Hair loss"],"answer":0},{"q":"Why does she get a stool softener?","options":["She has a fever","She can't sleep","Her pain medicine can cause constipation"],"answer":2}],"words":[{"en":"side effect","zh":"副作用"},{"en":"heart rate","zh":"心跳速率"},{"en":"lightheaded","zh":"頭昏的"},{"en":"stool softener","zh":"軟便劑"},{"en":"constipation","zh":"便祕"}]},{"id":"nl-07","title":"Blood Sugar Before Lunch","scene":"午餐前測血糖、打速效胰島素","level":"B1","accent":"en-AU","you":"Nurse Brooks","emma":"Mr. Nguyen","dialogue":[{"who":"Nurse Brooks","en":"Hi, Mr. Nguyen. Lunch is coming soon, so I need to check your blood sugar.","zh":"嗨，阮先生。午餐快來了，我要幫你測血糖。"},{"who":"Mr. Nguyen","en":"The finger stick again?","zh":"又要扎手指？"},{"who":"Nurse Brooks","en":"Yes, sorry. It's quick. I'll use the side of your finger. It hurts less there.","zh":"對，抱歉，很快。我扎手指側邊，比較不痛。"},{"who":"Mr. Nguyen","en":"OK, go ahead.","zh":"好，來吧。"},{"who":"Nurse Brooks","en":"It's two hundred and ten. That's higher than we want.","zh":"210，比我們希望的高。"},{"who":"Mr. Nguyen","en":"I ate some biscuits my daughter brought.","zh":"我吃了女兒帶來的餅乾。"},{"who":"Nurse Brooks","en":"That explains it. The doctor ordered fast-acting insulin with your meals. I'll give it as soon as your tray arrives.","zh":"那就說得通了。醫師開了配餐的速效胰島素，你的餐一送到我就幫你打。"},{"who":"Mr. Nguyen","en":"Where will you give it?","zh":"打哪裡？"},{"who":"Nurse Brooks","en":"In your belly, a few centimetres away from your belly button.","zh":"打在肚子，離肚臍幾公分的地方。"},{"who":"Mr. Nguyen","en":"Why do I have to eat right after?","zh":"為什麼打完要馬上吃？"},{"who":"Nurse Brooks","en":"This insulin works fast. If you don't eat, your blood sugar can drop too low.","zh":"這種胰島素作用很快，不吃東西血糖可能會掉太低。"}],"questions":[{"q":"What was Mr. Nguyen's blood sugar?","options":["Ninety","One hundred and ten","Two hundred and ten"],"answer":2},{"q":"Why was it high?","options":["He ate some biscuits","He missed his medicine","He walked too much"],"answer":0},{"q":"Why must he eat soon after the insulin?","options":["His blood sugar can drop too low","The food will get cold","His daughter is waiting"],"answer":0}],"words":[{"en":"blood sugar","zh":"血糖"},{"en":"finger stick","zh":"扎手指（測血糖）"},{"en":"insulin","zh":"胰島素"},{"en":"fast-acting","zh":"速效的"},{"en":"belly button","zh":"肚臍"}]},{"id":"nl-08","title":"Low Blood Sugar","scene":"病人發抖冒汗：測到低血糖，用果汁處理","level":"B1","accent":"en-US","you":"Nurse Bailey","emma":"Mrs. Allen","dialogue":[{"who":"Mrs. Allen","en":"Nurse, I feel shaky and sweaty.","zh":"護理師，我覺得發抖、一直冒汗。"},{"who":"Nurse Bailey","en":"Let me check your blood sugar right now. It's sixty-two. That's low.","zh":"我現在幫你測血糖。62，太低了。"},{"who":"Mrs. Allen","en":"What should I do?","zh":"我該怎麼辦？"},{"who":"Nurse Bailey","en":"Please drink this half cup of apple juice. It has sugar that works fast.","zh":"請喝這半杯蘋果汁，裡面的糖很快就會作用。"},{"who":"Mrs. Allen","en":"OK. I skipped breakfast because I wasn't hungry.","zh":"好。我沒吃早餐，因為不餓。"},{"who":"Nurse Bailey","en":"That's probably why. Your insulin still works even when you don't eat.","zh":"應該就是這個原因。你沒吃東西，胰島素還是會作用。"},{"who":"Mrs. Allen","en":"I didn't know that.","zh":"我不知道。"},{"who":"Nurse Bailey","en":"I'll check your sugar again in fifteen minutes. If it's still under seventy, you'll have more juice.","zh":"我 15 分鐘後再測一次。如果還是低於 70，就再喝一些果汁。"},{"who":"Mrs. Allen","en":"And then?","zh":"然後呢？"},{"who":"Nurse Bailey","en":"When it's normal, you should eat a snack with protein, like crackers and cheese, so it doesn't drop again.","zh":"正常之後，要吃一點有蛋白質的點心，像餅乾配起司，才不會再掉下來。"},{"who":"Mrs. Allen","en":"Thank you. I feel a little better already.","zh":"謝謝，我已經覺得好一點了。"}],"questions":[{"q":"What were Mrs. Allen's symptoms?","options":["Itching and a rash","Shaking and sweating","Headache and cough"],"answer":1},{"q":"What does the nurse give her first?","options":["Apple juice","Insulin","A sandwich"],"answer":0},{"q":"When will the nurse check her blood sugar again?","options":["Tomorrow","In fifteen minutes","In one hour"],"answer":1}],"words":[{"en":"shaky","zh":"發抖的"},{"en":"sweaty","zh":"冒汗的"},{"en":"low blood sugar","zh":"低血糖"},{"en":"skip","zh":"略過（沒吃）"},{"en":"protein","zh":"蛋白質"}]},{"id":"nl-09","title":"The Night Before Surgery","scene":"手術前一晚衛教：禁食、首飾、同意書","level":"B1","accent":"en-US","you":"Nurse Ortiz","emma":"Mr. Harris","dialogue":[{"who":"Nurse Ortiz","en":"Mr. Harris, your surgery is tomorrow at eight. I'd like to go over a few things.","zh":"Harris 先生，你的手術在明天八點，我想跟你說明幾件事。"},{"who":"Mr. Harris","en":"Sure. I'm a little nervous.","zh":"好，我有點緊張。"},{"who":"Nurse Ortiz","en":"That's normal. First, nothing to eat or drink after midnight. That includes water and gum.","zh":"這很正常。第一，半夜十二點以後不能吃也不能喝，包括水和口香糖。"},{"who":"Mr. Harris","en":"Not even water?","zh":"連水都不行？"},{"who":"Nurse Ortiz","en":"Not even water, unless the doctor says it's OK. An empty stomach keeps you safe during anesthesia.","zh":"連水都不行，除非醫師說可以。空腹能讓麻醉時比較安全。"},{"who":"Mr. Harris","en":"Got it.","zh":"了解。"},{"who":"Nurse Ortiz","en":"Second, please take off your ring and watch tonight and give them to your wife.","zh":"第二，今晚請把戒指和手錶拿下來交給你太太。"},{"who":"Mr. Harris","en":"What about my glasses?","zh":"那我的眼鏡呢？"},{"who":"Nurse Ortiz","en":"You can wear them until you go into the operating room.","zh":"可以戴到進手術室前。"},{"who":"Mr. Harris","en":"OK. Anything else?","zh":"好，還有嗎？"},{"who":"Nurse Ortiz","en":"The doctor will come to explain the surgery and the risks, and then you'll sign the consent form. Ask any questions before you sign.","zh":"醫師會來說明手術和風險，之後你會簽同意書。簽之前有任何問題都可以問。"}],"questions":[{"q":"When does Mr. Harris have to stop eating and drinking?","options":["After midnight","After breakfast","At eight in the evening"],"answer":0},{"q":"What should he give to his wife tonight?","options":["His glasses","His ring and watch","His phone"],"answer":1},{"q":"Who will explain the risks of the surgery?","options":["The doctor","His wife","The nurse"],"answer":0}],"words":[{"en":"surgery","zh":"手術"},{"en":"anesthesia","zh":"麻醉"},{"en":"empty stomach","zh":"空腹"},{"en":"operating room","zh":"手術室"},{"en":"consent form","zh":"同意書"}]},{"id":"nl-10","title":"Breathing Exercises After Surgery","scene":"術後教深呼吸、誘發性肺量計和咳嗽時壓枕頭","level":"B1","accent":"en-US","you":"Nurse Moore","emma":"Mrs. Scott","dialogue":[{"who":"Nurse Moore","en":"How are you feeling, Mrs. Scott?","zh":"Scott 太太，覺得怎麼樣？"},{"who":"Mrs. Scott","en":"Sore. It hurts to breathe deeply.","zh":"很痠痛，深呼吸會痛。"},{"who":"Nurse Moore","en":"I understand. But deep breathing is very important after surgery. It helps prevent pneumonia.","zh":"我了解，可是術後深呼吸很重要，可以預防肺炎。"},{"who":"Mrs. Scott","en":"How do I do it?","zh":"要怎麼做？"},{"who":"Nurse Moore","en":"This is an incentive spirometer. Breathe out first, then close your lips around the mouthpiece.","zh":"這是誘發性肺量計。先吐氣，再用嘴唇含住吸嘴。"},{"who":"Mrs. Scott","en":"Like this?","zh":"像這樣嗎？"},{"who":"Nurse Moore","en":"Yes. Now breathe in slowly and deeply, and try to raise the ball. Hold your breath for a few seconds.","zh":"對。現在慢慢深吸氣，讓球升起來，憋氣幾秒鐘。"},{"who":"Mrs. Scott","en":"That's hard.","zh":"好難。"},{"who":"Nurse Moore","en":"You did well. Try to do this ten times every hour while you're awake.","zh":"你做得很好。醒著的時候每小時做 10 次。"},{"who":"Mrs. Scott","en":"It hurts my stomach when I cough.","zh":"我咳嗽的時候肚子會痛。"},{"who":"Nurse Moore","en":"Hold this pillow against your stomach when you cough. It will hurt less.","zh":"咳嗽的時候把枕頭壓在肚子上，就比較不痛。"}],"questions":[{"q":"Why is deep breathing important after surgery?","options":["It helps prevent pneumonia","It helps her sleep","It lowers her blood sugar"],"answer":0},{"q":"How often should she use the spirometer?","options":["Ten times every hour while awake","Once a day","Only at night"],"answer":0},{"q":"What can she do to make coughing hurt less?","options":["Drink cold water","Lie on her stomach","Hold a pillow against her stomach"],"answer":2}],"words":[{"en":"sore","zh":"痠痛的"},{"en":"pneumonia","zh":"肺炎"},{"en":"incentive spirometer","zh":"誘發性肺量計"},{"en":"mouthpiece","zh":"吸嘴"},{"en":"cough","zh":"咳嗽"}]},{"id":"nl-11","title":"Changing a Dressing","scene":"換藥：觀察傷口、說明感染徵象","level":"B1","accent":"en-GB","you":"Nurse Evans","emma":"Mr. Clarke","dialogue":[{"who":"Nurse Evans","en":"Mr. Clarke, I'm going to change the dressing on your leg now.","zh":"Clarke 先生，我現在要幫你腿上的傷口換藥。"},{"who":"Mr. Clarke","en":"Will it hurt?","zh":"會痛嗎？"},{"who":"Nurse Evans","en":"It might sting a little when I clean it. Tell me if you need me to stop.","zh":"清的時候可能會有點刺痛，需要我停下來就告訴我。"},{"who":"Mr. Clarke","en":"All right.","zh":"好。"},{"who":"Nurse Evans","en":"First I'll wash my hands and put on gloves. The wound looks clean. There's no redness and no bad smell.","zh":"我先洗手、戴手套。傷口看起來很乾淨，沒有發紅，也沒有異味。"},{"who":"Mr. Clarke","en":"That's good news.","zh":"太好了。"},{"who":"Nurse Evans","en":"Yes, it's healing well. I'll put on a new dressing. Try to keep it dry when you have a wash.","zh":"對，癒合得很好。我幫你換上新的敷料。洗澡的時候盡量保持乾燥。"},{"who":"Mr. Clarke","en":"How will I know if it gets infected?","zh":"我怎麼知道有沒有感染？"},{"who":"Nurse Evans","en":"Watch for more redness, swelling, pus, or a fever. If you notice any of these, tell us straight away.","zh":"注意有沒有變得更紅、腫、有膿，或發燒。有任何一樣要馬上告訴我們。"},{"who":"Mr. Clarke","en":"Pus? That sounds awful.","zh":"膿？聽起來好可怕。"},{"who":"Nurse Evans","en":"Don't worry. Your wound looks great today.","zh":"別擔心，你的傷口今天看起來很好。"}],"questions":[{"q":"What does the nurse do before cleaning the wound?","options":["Takes his blood pressure","Gives him medicine","Washes her hands and puts on gloves"],"answer":2},{"q":"How does the wound look today?","options":["Red and swollen","Bleeding a lot","Clean and healing well"],"answer":2},{"q":"Which one is a sign of infection?","options":["Pus","A small scar","Dry skin"],"answer":0}],"words":[{"en":"dressing","zh":"敷料"},{"en":"sting","zh":"刺痛"},{"en":"wound","zh":"傷口"},{"en":"infected","zh":"感染的"},{"en":"pus","zh":"膿"},{"en":"swelling","zh":"腫脹"}]},{"id":"nl-12","title":"The IV Pump Is Beeping","scene":"點滴機在響：處理管路，發現注射部位腫脹（輸的是一般點滴：生理食鹽水）","level":"B1","accent":"en-US","you":"Nurse Wright","emma":"Mr. Young","dialogue":[{"who":"Mr. Young","en":"Nurse, the machine keeps beeping.","zh":"護理師，機器一直在叫。"},{"who":"Nurse Wright","en":"Let me check. The line was bent under your arm. I'll straighten it.","zh":"我看一下。管子被你手臂壓到折到了，我把它拉直。"},{"who":"Mr. Young","en":"Oh, sorry.","zh":"喔，抱歉。"},{"who":"Nurse Wright","en":"No problem, it happens a lot. Now let me look at your IV site. Does it hurt here?","zh":"沒關係，很常發生。現在讓我看看你的打針部位，這裡會痛嗎？"},{"who":"Mr. Young","en":"A little. It feels cold.","zh":"有一點，感覺涼涼的。"},{"who":"Nurse Wright","en":"The skin is a bit swollen and cool. I think the fluid is going into the tissue, not into the vein. This is called infiltration.","zh":"皮膚有點腫、涼涼的。我想點滴跑到組織裡，不是在血管裡，這叫做點滴滲漏（浸潤）。"},{"who":"Mr. Young","en":"Is that dangerous?","zh":"危險嗎？"},{"who":"Nurse Wright","en":"Your IV is plain saline, so it is usually not serious, but I'm stopping it now. I'll check the area, measure the swelling, and tell your doctor.","zh":"你打的是一般生理食鹽水，通常不嚴重，但我現在先把點滴停掉。我會檢查這一區、量腫的範圍，並告訴醫師。"},{"who":"Mr. Young","en":"What happens next?","zh":"接下來呢？"},{"who":"Nurse Wright","en":"For plain fluids like yours, our hospital's steps are to take this IV out and start a new one in your other arm. Some medicines need different steps, so we always check what is running first.","zh":"像你這種一般點滴，醫院的流程是把這條拔掉，在另一隻手重新打一條。有些藥物的處理步驟不一樣，所以我們一定先確認輸的是什麼。"},{"who":"Mr. Young","en":"Another needle?","zh":"又要扎針？"},{"who":"Nurse Wright","en":"I'm sorry, yes. I'll put this arm up on a pillow to help the swelling go down.","zh":"抱歉，對。我會把這隻手墊枕頭抬高，幫助消腫。"},{"who":"Mr. Young","en":"OK. Thank you for checking.","zh":"好，謝謝你檢查。"}],"questions":[{"q":"Why was the machine beeping?","options":["The battery was low","The line was bent","The bag was empty"],"answer":1},{"q":"What did the nurse notice at the IV site?","options":["It was swollen and cool","It was bleeding","It was hot and red"],"answer":0},{"q":"What will the nurse do?","options":["Give him pain medicine","Call his family","Start a new IV in his other arm"],"answer":2}],"words":[{"en":"IV","zh":"點滴（靜脈注射）"},{"en":"IV site","zh":"注射部位"},{"en":"beep","zh":"嗶嗶響"},{"en":"vein","zh":"靜脈"},{"en":"tissue","zh":"組織"},{"en":"infiltration","zh":"（點滴）滲漏、浸潤"}]},{"id":"nl-13","title":"Handoff Report","scene":"交班：把病人的狀況交給下一班的護理師","level":"B1","accent":"en-GB","you":"Nurse Diaz","emma":"Nurse Sam","dialogue":[{"who":"Nurse Diaz","en":"Hi, Sam. Are you ready for report on Room 12?","zh":"嗨 Sam，可以交 12 房了嗎？"},{"who":"Nurse Sam","en":"Yes, go ahead.","zh":"可以，請說。"},{"who":"Nurse Diaz","en":"Mr. Turner is seventy-two. He came in yesterday with pneumonia.","zh":"Turner 先生 72 歲，昨天因為肺炎住院。"},{"who":"Nurse Sam","en":"How is he doing now?","zh":"他現在怎麼樣？"},{"who":"Nurse Diaz","en":"His temperature was thirty-eight point five at four o'clock, so I gave him paracetamol. It's now thirty-seven point eight.","zh":"四點體溫 38.5 度，我給了 paracetamol，現在是 37.8 度。"},{"who":"Nurse Sam","en":"And his breathing?","zh":"呼吸呢？"},{"who":"Nurse Diaz","en":"He's on two litres of oxygen. His oxygen level is ninety-four percent.","zh":"他用 2 公升氧氣，血氧 94%。"},{"who":"Nurse Sam","en":"Is he on IV antibiotics?","zh":"有在打靜脈抗生素嗎？"},{"who":"Nurse Diaz","en":"Yes, the next dose is due at eight. Please also check that he's drinking enough. He's only had about two cups today.","zh":"有，下一劑八點要給。也請注意他水喝得夠不夠，他今天只喝了大約兩杯。"},{"who":"Nurse Sam","en":"Got it. Antibiotic at eight, and watch his fluids and his temperature.","zh":"了解。八點抗生素，注意他的水分和體溫。"},{"who":"Nurse Diaz","en":"Exactly. Let's go and see him together.","zh":"沒錯，我們一起去看他。"}],"questions":[{"q":"Why is Mr. Turner in hospital?","options":["Diabetes","Pneumonia","A broken leg"],"answer":1},{"q":"What medicine did the nurse give for his fever?","options":["Insulin","An antibiotic","Paracetamol"],"answer":2},{"q":"What should the next nurse watch?","options":["His fluids and his temperature","His weight and his sleep","His blood sugar"],"answer":0}],"words":[{"en":"report","zh":"交班報告"},{"en":"pneumonia","zh":"肺炎"},{"en":"antibiotic","zh":"抗生素"},{"en":"due","zh":"（藥）該給了"},{"en":"fluids","zh":"水分攝取"}]},{"id":"nl-14","title":"Calling the Doctor","scene":"術後血壓掉：打電話用 SBAR 報告醫師，最後複誦醫囑","level":"B2","accent":"en-US","you":"Nurse Reed","emma":"Dr. Shaw","dialogue":[{"who":"Nurse Reed","en":"Hello, Dr. Shaw. This is Alex Reed, the nurse on 5 West. I'm calling about Mrs. Gomez in Room 8.","zh":"Shaw 醫師你好，我是 5 西的護理師 Alex Reed，我打來是關於 8 房的 Gomez 太太。"},{"who":"Dr. Shaw","en":"Yes, what's going on?","zh":"好，怎麼了？"},{"who":"Nurse Reed","en":"Her blood pressure is eighty-eight over fifty. Two hours ago, it was one hundred and twenty over seventy.","zh":"她的血壓 88/50，兩小時前是 120/70。"},{"who":"Dr. Shaw","en":"Any other changes?","zh":"還有其他變化嗎？"},{"who":"Nurse Reed","en":"Her heart rate is one hundred and ten, and she says she feels dizzy. She had hip surgery this morning.","zh":"她心跳 110，說頭暈。她今天早上做了髖關節手術。"},{"who":"Dr. Shaw","en":"Is there any bleeding from the wound?","zh":"傷口有流血嗎？"},{"who":"Nurse Reed","en":"The dressing has new blood on it, about the size of my hand.","zh":"敷料上有新的血跡，大概我手掌這麼大。"},{"who":"Dr. Shaw","en":"OK. What do you think is happening?","zh":"好。你覺得是怎麼回事？"},{"who":"Nurse Reed","en":"I'm worried she's bleeding. I'd like you to come and see her. Can I give her IV fluids and send some blood tests?","zh":"我擔心她在出血。希望你過來看她。我可以先給她點滴、抽血檢驗嗎？"},{"who":"Dr. Shaw","en":"Yes. Give five hundred milliliters of normal saline and send a blood count. I'll be there in ten minutes.","zh":"好。給 500 毫升生理食鹽水，抽血球計數，我十分鐘內到。"},{"who":"Nurse Reed","en":"Let me read that back: five hundred milliliters of normal saline now, and a blood count. You'll be here in ten minutes.","zh":"我複誦一次：現在給 500 毫升生理食鹽水，抽血球計數。你十分鐘內到。"}],"questions":[{"q":"Why is the nurse calling the doctor?","options":["The patient has a rash","The patient's blood pressure dropped","The patient wants to go home"],"answer":1},{"q":"What did the nurse see on the dressing?","options":["Nothing","New blood","Pus"],"answer":1},{"q":"Why does the nurse repeat the doctor's order?","options":["To check that she heard it correctly","The phone is broken","She forgot her pen"],"answer":0}],"words":[{"en":"heart rate","zh":"心跳"},{"en":"bleeding","zh":"出血"},{"en":"normal saline","zh":"生理食鹽水"},{"en":"blood count","zh":"血球計數"},{"en":"read back","zh":"複誦（醫囑）"}]},{"id":"nl-15","title":"A Phone Call From the Family","scene":"兒子打電話問病情：先確認病人同意、核對通關密語","level":"B1","accent":"en-US","you":"Nurse Hall","emma":"Mr. Price","dialogue":[{"who":"Nurse Hall","en":"Good afternoon, 6 East. This is Jordan.","zh":"午安，6 東，我是 Jordan。"},{"who":"Mr. Price","en":"Hi, I'm calling about my mother, Ruth Price. How is she doing?","zh":"嗨，我打來問我媽媽 Ruth Price，她還好嗎？"},{"who":"Nurse Hall","en":"Thank you for calling. Before I share any information, I need to check that your mother gave permission. Can I have your name?","zh":"謝謝你打來。在告訴你任何資訊之前，我要確認你媽媽有沒有同意。請問你的名字？"},{"who":"Mr. Price","en":"Michael Price. I'm her son.","zh":"Michael Price，我是她兒子。"},{"who":"Nurse Hall","en":"Thank you, Michael. Yes, you're on her list. She also gave us a code word. Can you tell me the code word?","zh":"謝謝你 Michael。有，你在她的名單上。她也給了我們一個通關密語，可以告訴我嗎？"},{"who":"Mr. Price","en":"Sunflower.","zh":"向日葵。"},{"who":"Nurse Hall","en":"That's right. She's doing better today. Her fever is gone, and she walked in the hallway this morning.","zh":"對。她今天好一點了，燒退了，早上還在走廊走路。"},{"who":"Mr. Price","en":"That's great. When can she come home?","zh":"太好了。她什麼時候可以回家？"},{"who":"Nurse Hall","en":"The doctor will decide tomorrow. If you like, you can come during the doctor's rounds at nine and ask her yourself.","zh":"醫師明天會決定。你願意的話，可以九點醫師查房時過來自己問她。"},{"who":"Mr. Price","en":"I'll be there. Thank you so much.","zh":"我會過去，非常謝謝你。"},{"who":"Nurse Hall","en":"You're welcome. I'll tell your mom you called.","zh":"不客氣，我會告訴你媽媽你打來過。"}],"questions":[{"q":"Why does the nurse ask for the code word?","options":["To find the room number","To protect the patient's privacy","To make a joke"],"answer":1},{"q":"How is Mrs. Price today?","options":["Worse than yesterday","Still very sick in bed","Better, and her fever is gone"],"answer":2},{"q":"When can Michael talk to the doctor?","options":["During the doctor's rounds at nine","Next week","Tonight at nine"],"answer":0}],"words":[{"en":"permission","zh":"許可、同意"},{"en":"privacy","zh":"隱私"},{"en":"code word","zh":"通關密語"},{"en":"rounds","zh":"查房"},{"en":"hallway","zh":"走廊"}]},{"id":"nl-16","title":"A Patient Refuses Medicine","scene":"病人不想吃抗凝血藥：問原因、說明、給替代方法","level":"B1","accent":"en-US","you":"Nurse Cruz","emma":"Mr. Adams","dialogue":[{"who":"Nurse Cruz","en":"Mr. Adams, here is your blood thinner.","zh":"Adams 先生，這是你的抗凝血藥。"},{"who":"Mr. Adams","en":"I don't want it.","zh":"我不想吃。"},{"who":"Nurse Cruz","en":"OK. Can you tell me why?","zh":"好，可以告訴我為什麼嗎？"},{"who":"Mr. Adams","en":"It makes my gums bleed when I brush my teeth. I don't like it.","zh":"刷牙的時候牙齦會流血，我不喜歡。"},{"who":"Nurse Cruz","en":"That can happen with this medicine. Thank you for telling me. Is it a lot of blood or just a little?","zh":"這個藥是可能會這樣，謝謝你告訴我。血很多還是一點點？"},{"who":"Mr. Adams","en":"Just a little. But it scares me.","zh":"一點點，可是我會怕。"},{"who":"Nurse Cruz","en":"I understand. This medicine helps prevent blood clots in your legs and lungs. A clot can be very dangerous.","zh":"我了解。這個藥可以預防腿和肺長血塊，血塊可能非常危險。"},{"who":"Mr. Adams","en":"I didn't know it was that important.","zh":"我不知道那麼重要。"},{"who":"Nurse Cruz","en":"A soft toothbrush can help your gums. I'll also tell your doctor about the bleeding.","zh":"用軟毛牙刷對牙齦會比較好。我也會告訴醫師你牙齦流血的事。"},{"who":"Mr. Adams","en":"OK. I'll take it today.","zh":"好，我今天會吃。"},{"who":"Nurse Cruz","en":"Thank you. And if you see blood in your urine or stool, tell me right away.","zh":"謝謝。如果小便或大便有血，要馬上告訴我。"}],"questions":[{"q":"Why doesn't Mr. Adams want the medicine?","options":["It makes his gums bleed","It tastes bad","It is too expensive"],"answer":0},{"q":"What does this medicine help prevent?","options":["Infections","Headaches","Blood clots"],"answer":2},{"q":"What does the nurse suggest for his gums?","options":["Use mouthwash only","Use a soft toothbrush","Stop brushing his teeth"],"answer":1}],"words":[{"en":"blood thinner","zh":"抗凝血藥"},{"en":"gums","zh":"牙齦"},{"en":"blood clot","zh":"血塊"},{"en":"refuse","zh":"拒絕"},{"en":"urine","zh":"尿液"}]},{"id":"nl-17","title":"Going Home","scene":"心衰竭病人出院衛教：吃藥、量體重、回診，最後用自己的話說一次","level":"B1","accent":"en-US","you":"Nurse Lopez","emma":"Mrs. Baker","dialogue":[{"who":"Nurse Lopez","en":"Mrs. Baker, you're going home today. Let's go over your instructions.","zh":"Baker 太太，你今天出院，我們來看一下注意事項。"},{"who":"Mrs. Baker","en":"Great. I'm ready.","zh":"太好了，我準備好了。"},{"who":"Nurse Lopez","en":"You have a new heart medicine. Take one pill every morning, even if you feel fine.","zh":"你有一種新的心臟藥，每天早上吃一顆，就算覺得沒事也要吃。"},{"who":"Mrs. Baker","en":"Every morning. OK.","zh":"每天早上，好。"},{"who":"Nurse Lopez","en":"Weigh yourself every morning too, after you use the bathroom. Write it down.","zh":"每天早上上完廁所也要量體重，記下來。"},{"who":"Mrs. Baker","en":"Why do I need to weigh myself?","zh":"為什麼要量體重？"},{"who":"Nurse Lopez","en":"If you gain more than two pounds in one day, or five pounds in a week, your body may be keeping fluid. Call your doctor.","zh":"如果一天重了超過 2 磅，或一週超過 5 磅，可能是身體在積水，要打電話給醫師。"},{"who":"Mrs. Baker","en":"Two pounds in a day, five in a week. Got it.","zh":"一天 2 磅、一週 5 磅，知道了。"},{"who":"Nurse Lopez","en":"Your follow-up appointment is next Tuesday at ten.","zh":"回診時間是下週二十點。"},{"who":"Mrs. Baker","en":"And when should I come back to the hospital?","zh":"那什麼時候要回醫院？"},{"who":"Nurse Lopez","en":"Call 911 if you have chest pain or can't breathe. Now, can you tell me in your own words when to call the doctor?","zh":"胸痛或喘不過氣要打 911。現在，可以用你自己的話告訴我什麼時候要打給醫師嗎？"}],"questions":[{"q":"When should Mrs. Baker weigh herself?","options":["Once a week","Every night after dinner","Every morning after using the bathroom"],"answer":2},{"q":"When should she call her doctor?","options":["If she sleeps badly","If she gains two pounds in one day","If she feels hungry"],"answer":1},{"q":"What should she do if she has chest pain?","options":["Weigh herself again","Call 911","Wait until Tuesday"],"answer":1}],"words":[{"en":"instructions","zh":"注意事項"},{"en":"weigh","zh":"量體重"},{"en":"gain","zh":"增加"},{"en":"follow-up appointment","zh":"回診"},{"en":"in your own words","zh":"用自己的話"}]},{"id":"nl-18","title":"Chest Pain","scene":"病人突然胸痛：快速評估、找人幫忙、做心電圖","level":"B1","accent":"en-US","you":"Nurse Chang","emma":"Mr. King","dialogue":[{"who":"Mr. King","en":"Nurse, my chest hurts.","zh":"護理師，我胸口好痛。"},{"who":"Nurse Chang","en":"Mr. King, I'm here. Where exactly is the pain?","zh":"King 先生，我在這。哪裡痛？"},{"who":"Mr. King","en":"In the middle. It feels heavy, like something is sitting on me.","zh":"中間，很重，好像有東西壓著。"},{"who":"Nurse Chang","en":"Does the pain go anywhere else?","zh":"會痛到別的地方嗎？"},{"who":"Mr. King","en":"My left arm and my jaw.","zh":"左手臂和下巴。"},{"who":"Nurse Chang","en":"I'm going to call for help, and I'll stay with you. Can I get some help in Room 3, please? Chest pain!","zh":"我要叫人來幫忙，我會陪著你。3 房需要幫忙，胸痛！"},{"who":"Mr. King","en":"Am I having a heart attack?","zh":"我是心臟病發作嗎？"},{"who":"Nurse Chang","en":"We're going to find out. We'll do an ECG right now to look at your heart.","zh":"我們會查清楚，現在馬上做心電圖看你的心臟。"},{"who":"Mr. King","en":"I'm scared.","zh":"我好怕。"},{"who":"Nurse Chang","en":"I know. Try to breathe slowly. The doctor is coming, and we'll give you medicine to help.","zh":"我知道。試著慢慢呼吸。醫師快到了，我們會給你藥。"},{"who":"Mr. King","en":"OK. Please don't leave.","zh":"好，拜託不要走。"}],"questions":[{"q":"How does Mr. King describe the pain?","options":["Sharp and burning","Heavy, like something is sitting on him","Itchy"],"answer":1},{"q":"Where else does the pain go?","options":["His stomach","His left arm and his jaw","His back and his legs"],"answer":1},{"q":"What test will they do right away?","options":["An ECG","An X-ray of his leg","A blood sugar test"],"answer":0}],"words":[{"en":"chest pain","zh":"胸痛"},{"en":"jaw","zh":"下巴"},{"en":"heart attack","zh":"心臟病發作（心肌梗塞）"},{"en":"ECG","zh":"心電圖"},{"en":"scared","zh":"害怕的"}]},{"id":"nl-19","title":"Short of Breath","scene":"病人喘：扶坐起、給氧、教噘嘴呼吸","level":"B1","accent":"en-GB","you":"Nurse Ali","emma":"Mrs. Hughes","dialogue":[{"who":"Mrs. Hughes","en":"I can't get my breath.","zh":"我喘不過氣。"},{"who":"Nurse Ali","en":"Mrs. Hughes, I'm going to help you sit up. Sitting up makes breathing easier.","zh":"Hughes 太太，我扶你坐起來，坐起來比較好呼吸。"},{"who":"Mrs. Hughes","en":"Thank you.","zh":"謝謝。"},{"who":"Nurse Ali","en":"I'm putting the oxygen on now. This tube goes in your nose.","zh":"我現在幫你戴氧氣，這條管子放在鼻子裡。"},{"who":"Mrs. Hughes","en":"OK.","zh":"好。"},{"who":"Nurse Ali","en":"Your oxygen level was eighty-nine. Let's wait a minute. It's ninety-three now. That's better.","zh":"你剛剛的血氧是 89，我們等一分鐘。現在 93，好多了。"},{"who":"Mrs. Hughes","en":"It's a bit easier now.","zh":"現在比較好呼吸了。"},{"who":"Nurse Ali","en":"Good. Try breathing in through your nose and out slowly through your lips, like you're blowing out a candle.","zh":"很好。試著用鼻子吸氣，再用嘴唇慢慢吐氣，像吹蠟燭一樣。"},{"who":"Mrs. Hughes","en":"Like this?","zh":"像這樣？"},{"who":"Nurse Ali","en":"Perfect. I'll stay for a few minutes, and then I'll ask the doctor to come and listen to your chest.","zh":"很好。我會在這裡待幾分鐘，再請醫師來聽你的胸部。"},{"who":"Mrs. Hughes","en":"Please don't go far.","zh":"不要走太遠。"}],"questions":[{"q":"What does the nurse do first?","options":["Helps her sit up","Takes her temperature","Gives her water"],"answer":0},{"q":"What was her oxygen level after the oxygen?","options":["Ninety-nine","Ninety-three","Eighty-nine"],"answer":1},{"q":"How should she breathe out?","options":["Slowly through her lips","She should hold her breath","Quickly through her nose"],"answer":0}],"words":[{"en":"short of breath","zh":"呼吸急促（喘）"},{"en":"sit up","zh":"坐起來"},{"en":"oxygen","zh":"氧氣"},{"en":"tube","zh":"管子"},{"en":"blow out","zh":"吹熄"}]},{"id":"nl-20","title":"Visiting an Isolation Room","scene":"接觸隔離病房：教訪客洗手、穿隔離衣和手套","level":"B1","accent":"en-US","you":"Nurse Ford","emma":"Ms. Green","dialogue":[{"who":"Ms. Green","en":"Hi, I'm here to see my husband, Paul Green.","zh":"嗨，我來看我先生 Paul Green。"},{"who":"Nurse Ford","en":"Hi. Before you go in, I need to explain something. Your husband has an infection that can spread by touch, so he's in contact isolation.","zh":"嗨，進去前我要先說明一件事。你先生的感染會透過接觸傳染，所以他在接觸隔離。"},{"who":"Ms. Green","en":"Is it dangerous for me?","zh":"對我危險嗎？"},{"who":"Nurse Ford","en":"You can visit him safely if you follow a few steps. First, wash your hands or use this hand gel.","zh":"只要照幾個步驟就可以安全探視。首先洗手或用這個乾洗手。"},{"who":"Ms. Green","en":"OK.","zh":"好。"},{"who":"Nurse Ford","en":"Then put on this yellow gown and these gloves.","zh":"然後穿上這件黃色隔離衣、戴上這副手套。"},{"who":"Ms. Green","en":"Do I need a mask too?","zh":"也要戴口罩嗎？"},{"who":"Nurse Ford","en":"For this infection, you don't need a mask. When you leave, take off the gloves and the gown inside the room and put them in this bin.","zh":"這種感染不需要口罩。離開時，在病房裡脫掉手套和隔離衣，丟進這個桶子。"},{"who":"Ms. Green","en":"And then wash my hands again?","zh":"然後再洗一次手？"},{"who":"Nurse Ford","en":"Exactly. And please put his clothes in a bag before you take them home.","zh":"沒錯。他的衣服也要先裝袋再帶回家。"},{"who":"Ms. Green","en":"Thank you for explaining.","zh":"謝謝你說明。"}],"questions":[{"q":"How can her husband's infection spread?","options":["Through food","Through the air","By touch"],"answer":2},{"q":"What must she wear?","options":["A gown and gloves","A mask and glasses","Nothing special"],"answer":0},{"q":"Where should she take off the gown?","options":["At home","In the hallway","Inside the room"],"answer":2}],"words":[{"en":"isolation","zh":"隔離"},{"en":"infection","zh":"感染"},{"en":"spread","zh":"傳播"},{"en":"gown","zh":"隔離衣"},{"en":"bin","zh":"垃圾桶"}]},{"id":"nl-21","title":"Turning in Bed","scene":"臥床病人每兩小時翻身，預防壓瘡","level":"A2","accent":"en-AU","you":"Nurse Walsh","emma":"Mr. Bell","dialogue":[{"who":"Nurse Walsh","en":"Hi, Mr. Bell. It's two o'clock, so it's time to turn you onto your side.","zh":"嗨 Bell 先生，兩點了，該幫你翻身側躺了。"},{"who":"Mr. Bell","en":"Again? I just got comfortable.","zh":"又要？我才剛躺舒服。"},{"who":"Nurse Walsh","en":"I know, sorry. We turn you every two hours to protect your skin.","zh":"我知道，抱歉。我們每兩小時幫你翻身，保護你的皮膚。"},{"who":"Mr. Bell","en":"What's wrong with my skin?","zh":"我的皮膚怎麼了？"},{"who":"Nurse Walsh","en":"Nothing yet. But when you lie in one position for a long time, the skin over your bones can get a sore.","zh":"現在還沒事。可是一直躺同一個姿勢，骨頭突出地方的皮膚會長瘡。"},{"who":"Mr. Bell","en":"You mean a bed sore?","zh":"你是說褥瘡嗎？"},{"who":"Nurse Walsh","en":"Yes, exactly. Let me check your heels and your lower back. They look fine.","zh":"對。我看一下你的腳跟和下背。看起來都很好。"},{"who":"Mr. Bell","en":"Good.","zh":"很好。"},{"who":"Nurse Walsh","en":"I'll put one pillow between your knees and one behind your back.","zh":"我在你兩膝中間放一個枕頭，背後再放一個。"},{"who":"Mr. Bell","en":"That's nice, actually.","zh":"其實還蠻舒服的。"},{"who":"Nurse Walsh","en":"Great. I'll be back at four to turn you to the other side.","zh":"很好，我四點再來幫你翻到另一邊。"}],"questions":[{"q":"How often does the nurse turn Mr. Bell?","options":["Every four hours","Every two hours","Once a day"],"answer":1},{"q":"Why does she turn him?","options":["To check his blood pressure","To protect his skin","To help him sleep"],"answer":1},{"q":"Where does she put the pillows?","options":["Between his knees and behind his back","Under his head only","Under his feet"],"answer":0}],"words":[{"en":"turn","zh":"翻身"},{"en":"position","zh":"姿勢"},{"en":"bed sore","zh":"褥瘡（壓瘡）"},{"en":"heel","zh":"腳跟"},{"en":"lower back","zh":"下背"}]},{"id":"nl-22","title":"Nausea After Chemotherapy","scene":"化療後噁心：給止吐藥、飲食建議","level":"B1","accent":"en-US","you":"Nurse Rossi","emma":"Ms. Ward","dialogue":[{"who":"Ms. Ward","en":"I feel so sick. I can't eat anything.","zh":"我好想吐，什麼都吃不下。"},{"who":"Nurse Rossi","en":"I'm sorry. Nausea is common after chemotherapy. Have you vomited?","zh":"很抱歉，化療後噁心很常見。你有吐嗎？"},{"who":"Ms. Ward","en":"Twice this morning.","zh":"早上吐了兩次。"},{"who":"Nurse Rossi","en":"The doctor ordered a medicine for nausea. I'll give it to you now. It works best before you eat.","zh":"醫師有開止吐藥，我現在給你。在吃東西前用效果最好。"},{"who":"Ms. Ward","en":"Thank you.","zh":"謝謝。"},{"who":"Nurse Rossi","en":"Try small meals, maybe five or six times a day, instead of three big ones.","zh":"試試少量多餐，一天吃五六次，不要三大餐。"},{"who":"Ms. Ward","en":"What kind of food?","zh":"吃什麼樣的東西？"},{"who":"Nurse Rossi","en":"Plain, dry food is usually easier, like crackers or toast. Avoid greasy food and strong smells.","zh":"清淡、乾的食物通常比較好入口，像蘇打餅或吐司。避開油膩的東西和重的味道。"},{"who":"Ms. Ward","en":"The smell of coffee makes me feel worse.","zh":"咖啡的味道讓我更想吐。"},{"who":"Nurse Rossi","en":"Then let's keep the coffee away. And sip water slowly, so you don't get dehydrated.","zh":"那我們讓咖啡遠離你。也要小口慢慢喝水，才不會脫水。"},{"who":"Ms. Ward","en":"OK. I'll try.","zh":"好，我試試看。"}],"questions":[{"q":"How many times did Ms. Ward vomit this morning?","options":["Once","Twice","Five times"],"answer":1},{"q":"What kind of food does the nurse suggest?","options":["Plain, dry food like crackers","Spicy food","Greasy food"],"answer":0},{"q":"Why should she sip water?","options":["To sleep better","To clean her teeth","So she doesn't get dehydrated"],"answer":2}],"words":[{"en":"nausea","zh":"噁心"},{"en":"vomit","zh":"嘔吐"},{"en":"chemotherapy","zh":"化學治療"},{"en":"greasy","zh":"油膩的"},{"en":"dehydrated","zh":"脫水的"}]},{"id":"nl-23","title":"Foot Care for Diabetes","scene":"糖尿病足部照護衛教","level":"B1","accent":"en-US","you":"Nurse Silva","emma":"Mr. Ross","dialogue":[{"who":"Nurse Silva","en":"Mr. Ross, people with diabetes need to take special care of their feet. Can I show you how?","zh":"Ross 先生，糖尿病的人要特別照顧腳，我示範給你看好嗎？"},{"who":"Mr. Ross","en":"My feet? Why?","zh":"我的腳？為什麼？"},{"who":"Nurse Silva","en":"Diabetes can make you lose feeling in your feet. You might not notice a small cut, and it can turn into a serious infection.","zh":"糖尿病會讓腳的感覺變差，你可能沒注意到小傷口，它可能變成嚴重感染。"},{"who":"Mr. Ross","en":"I didn't know that.","zh":"我不知道。"},{"who":"Nurse Silva","en":"So check your feet every day, even between your toes. Use a mirror to see the bottom.","zh":"所以每天都要檢查腳，連腳趾縫都要看。用鏡子看腳底。"},{"who":"Mr. Ross","en":"Every day? OK.","zh":"每天？好。"},{"who":"Nurse Silva","en":"Wash them in warm water, not hot water. Test the water with your elbow first.","zh":"用溫水洗，不要用熱水，先用手肘試水溫。"},{"who":"Mr. Ross","en":"Why my elbow?","zh":"為什麼用手肘？"},{"who":"Nurse Silva","en":"Because your feet may not feel that the water is too hot. Then dry them well, especially between the toes.","zh":"因為你的腳可能感覺不到水太燙。洗完要擦乾，特別是腳趾縫。"},{"who":"Mr. Ross","en":"Can I walk barefoot at home?","zh":"在家可以打赤腳嗎？"},{"who":"Nurse Silva","en":"No, always wear shoes or slippers, even at home. And call your doctor if you see a cut that doesn't heal.","zh":"不行，就算在家也要穿鞋或拖鞋。如果看到傷口一直不好，要打給醫師。"}],"questions":[{"q":"Why must Mr. Ross check his feet?","options":["He walks a lot","His shoes are old","He might not feel a small cut"],"answer":2},{"q":"How should he test the water?","options":["With a thermometer","With his elbow","With his foot"],"answer":1},{"q":"What does the nurse say about walking barefoot?","options":["Always wear shoes or slippers","It's good exercise","It's fine at home"],"answer":0}],"words":[{"en":"diabetes","zh":"糖尿病"},{"en":"toe","zh":"腳趾"},{"en":"barefoot","zh":"赤腳"},{"en":"heal","zh":"癒合"},{"en":"elbow","zh":"手肘"}]},{"id":"nl-24","title":"Confused at Night","scene":"年長病人半夜混亂想回家：安撫、告訴他人在哪、現在幾點","level":"B1","accent":"en-US","you":"Nurse Grant","emma":"Mrs. Wood","dialogue":[{"who":"Mrs. Wood","en":"Where am I? I need to go home and feed my cat!","zh":"我在哪裡？我要回家餵我的貓！"},{"who":"Nurse Grant","en":"Mrs. Wood, it's OK. You're in Saint Mary's Hospital. I'm Grant, your nurse.","zh":"Wood 太太，沒事的。你在聖瑪麗醫院，我是你的護理師 Grant。"},{"who":"Mrs. Wood","en":"Hospital? Why?","zh":"醫院？為什麼？"},{"who":"Nurse Grant","en":"You had an infection, and you're getting medicine to help you get better. It's three in the morning.","zh":"你有感染，正在用藥幫你好起來。現在是凌晨三點。"},{"who":"Mrs. Wood","en":"But my cat...","zh":"可是我的貓……"},{"who":"Nurse Grant","en":"Your daughter is feeding your cat. She told me this afternoon.","zh":"你女兒在幫你餵貓，她今天下午跟我說的。"},{"who":"Mrs. Wood","en":"Oh... good.","zh":"喔……那就好。"},{"who":"Nurse Grant","en":"Let me turn on a small light so you can see the room. Here are your glasses.","zh":"我幫你開一盞小燈，讓你看得到房間。這是你的眼鏡。"},{"who":"Mrs. Wood","en":"Thank you. Everything looked strange.","zh":"謝謝，剛剛什麼都看起來怪怪的。"},{"who":"Nurse Grant","en":"Would you like some water? I'll sit with you for a few minutes.","zh":"要喝點水嗎？我陪你坐幾分鐘。"},{"who":"Mrs. Wood","en":"Yes, please. You're very kind.","zh":"好，謝謝，你人真好。"}],"questions":[{"q":"What does Mrs. Wood want to do?","options":["Go home and feed her cat","Eat breakfast","Call her doctor"],"answer":0},{"q":"What time is it?","options":["Three in the morning","Three in the afternoon","Midnight"],"answer":0},{"q":"What does the nurse do to help her?","options":["Turns on a light and gives her glasses","Calls the police","Gives her sleeping pills"],"answer":0}],"words":[{"en":"confused","zh":"意識混亂的"},{"en":"infection","zh":"感染"},{"en":"feed","zh":"餵"},{"en":"glasses","zh":"眼鏡"},{"en":"strange","zh":"奇怪的"}]},{"id":"nl-25","title":"Before a Blood Transfusion","scene":"輸血前說明：兩人核對、前 15 分鐘觀察、輸血反應","level":"B2","accent":"en-US","you":"Nurse Hart","emma":"Mr. Perez","dialogue":[{"who":"Nurse Hart","en":"Mr. Perez, your blood count is low, so the doctor ordered one unit of blood.","zh":"Perez 先生，你的血球數偏低，醫師開了一單位的血。"},{"who":"Mr. Perez","en":"Is it safe?","zh":"安全嗎？"},{"who":"Nurse Hart","en":"Yes, it's very safe, and we check it carefully. Another nurse and I will check your name, your date of birth and the blood bag together.","zh":"很安全，我們會仔細核對。我和另一位護理師會一起核對你的名字、出生日期和血袋。"},{"who":"Mr. Perez","en":"Two nurses?","zh":"兩個護理師？"},{"who":"Nurse Hart","en":"Yes, two of us, every time. It's a safety rule. I'll also take your vital signs before we start.","zh":"對，每次都兩個人，這是安全規定。開始前我也會量你的生命徵象。"},{"who":"Mr. Perez","en":"How long does it take?","zh":"要多久？"},{"who":"Nurse Hart","en":"About two to three hours. I'll stay with you for the first fifteen minutes, because that's when reactions usually happen.","zh":"大概兩到三小時。前 15 分鐘我會陪在你旁邊，因為反應通常在那時候發生。"},{"who":"Mr. Perez","en":"What kind of reactions?","zh":"什麼樣的反應？"},{"who":"Nurse Hart","en":"Chills, fever, itching, a rash, back pain, or trouble breathing. If you feel any of these, press the call button right away.","zh":"發冷、發燒、癢、起疹子、背痛，或呼吸困難。有任何一樣要馬上按呼叫鈴。"},{"who":"Mr. Perez","en":"And what would you do?","zh":"那你會怎麼做？"},{"who":"Nurse Hart","en":"I'd stop the blood immediately, keep the IV open with saline, and call the doctor.","zh":"我會馬上停止輸血，用生理食鹽水維持點滴暢通，然後通知醫師。"}],"questions":[{"q":"Why does Mr. Perez need blood?","options":["He is going to have surgery","His blood count is low","He has a fever"],"answer":1},{"q":"Why does the nurse stay for the first fifteen minutes?","options":["The doctor asked her to talk to him","To take a break","Reactions usually happen then"],"answer":2},{"q":"What would the nurse do first if he had a reaction?","options":["Call his family","Give him more blood","Stop the blood immediately"],"answer":2}],"words":[{"en":"transfusion","zh":"輸血"},{"en":"blood count","zh":"血球數"},{"en":"unit","zh":"單位（血品）"},{"en":"chills","zh":"發冷"},{"en":"itching","zh":"癢"},{"en":"reaction","zh":"反應"}]},{"id":"nl-26","title":"Measuring Urine Output","scene":"導尿管照護：倒尿袋、記錄尿量、尿袋要低於膀胱","level":"B1","accent":"en-GB","you":"Nurse Collins","emma":"Mr. Fisher","dialogue":[{"who":"Nurse Collins","en":"Good morning, Mr. Fisher. I'm going to empty your catheter bag and measure your urine.","zh":"早安 Fisher 先生，我要幫你倒尿袋、量尿量。"},{"who":"Mr. Fisher","en":"Why do you measure it?","zh":"為什麼要量？"},{"who":"Nurse Collins","en":"It tells us how well your kidneys are working and whether you're drinking enough.","zh":"可以知道你的腎臟功能好不好，還有你水喝得夠不夠。"},{"who":"Mr. Fisher","en":"How much is there?","zh":"有多少？"},{"who":"Nurse Collins","en":"Four hundred millilitres since midnight. The colour is light yellow, which is good.","zh":"從半夜到現在 400 毫升，顏色淡黃，很好。"},{"who":"Mr. Fisher","en":"My wife keeps telling me to drink more.","zh":"我太太一直叫我多喝水。"},{"who":"Nurse Collins","en":"She's right. Unless the doctor tells you to limit fluids, try to drink a glass of water every couple of hours.","zh":"她說得對。除非醫師要你限水，盡量每兩三小時喝一杯水。"},{"who":"Mr. Fisher","en":"The tube pulls a bit when I move.","zh":"我動的時候管子會拉到。"},{"who":"Nurse Collins","en":"Let me tape it to your thigh so it doesn't pull. And always keep the bag below your bladder.","zh":"我把它貼在你大腿上就不會拉到。尿袋也要一直保持在比膀胱低的位置。"},{"who":"Mr. Fisher","en":"Below my bladder? Why?","zh":"比膀胱低？為什麼？"},{"who":"Nurse Collins","en":"So the urine doesn't flow back up. That helps prevent infection.","zh":"這樣尿液才不會倒流，可以預防感染。"}],"questions":[{"q":"What does the amount of urine tell the nurse?","options":["How well he slept","What he ate for dinner","How well his kidneys work and if he drinks enough"],"answer":2},{"q":"How much urine was there since midnight?","options":["Four litres","Four hundred millilitres","Forty millilitres"],"answer":1},{"q":"Why must the bag stay below his bladder?","options":["So he can see it","It looks tidier","So the urine doesn't flow back up"],"answer":2}],"words":[{"en":"catheter","zh":"導尿管"},{"en":"urine","zh":"尿液"},{"en":"kidney","zh":"腎臟"},{"en":"bladder","zh":"膀胱"},{"en":"thigh","zh":"大腿"}]},{"id":"nl-27","title":"Using a Metered-Dose Inhaler","scene":"教病人用定量噴霧型吸入器（要先搖的那種），最後請他做一次給你看（回覆示教）","level":"B1","accent":"en-US","you":"Nurse Bennett","emma":"Mr. Murphy","dialogue":[{"who":"Nurse Bennett","en":"Mr. Murphy, let me show you how to use your inhaler. This is a spray inhaler, a metered-dose inhaler. Many people use it the wrong way.","zh":"Murphy 先生，我示範吸入器怎麼用。這是噴霧型的，叫定量噴霧吸入器。很多人都用錯。"},{"who":"Mr. Murphy","en":"Really? I just press it.","zh":"真的嗎？我只是按一下。"},{"who":"Nurse Bennett","en":"This kind needs to be shaken, so first, shake it well and take off the cap. Then breathe out all the way.","zh":"這種要先搖，所以首先搖一搖、拿掉蓋子，然後把氣全部吐出來。"},{"who":"Mr. Murphy","en":"OK.","zh":"好。"},{"who":"Nurse Bennett","en":"Put the mouthpiece in your mouth and close your lips around it. Press it once and breathe in slowly and deeply at the same time.","zh":"把吸嘴放進嘴裡、嘴唇包住，按一下的同時慢慢深吸氣。"},{"who":"Mr. Murphy","en":"At the same time. Got it.","zh":"同時，知道了。"},{"who":"Nurse Bennett","en":"Then hold your breath for ten seconds, and breathe out slowly.","zh":"然後憋氣 10 秒，再慢慢吐氣。"},{"who":"Mr. Murphy","en":"Ten seconds. That's longer than I thought.","zh":"10 秒，比我想的久。"},{"who":"Nurse Bennett","en":"If you need a second puff, wait about one minute.","zh":"如果要吸第二下，大約等一分鐘。"},{"who":"Mr. Murphy","en":"OK.","zh":"好。"},{"who":"Mr. Murphy","en":"My wife has a powder inhaler. Should she shake hers too?","zh":"我太太用的是乾粉吸入器，她也要搖嗎？"},{"who":"Nurse Bennett","en":"Not always. Inhalers work differently, and many powder inhalers should not be shaken. She should follow the instructions for her own inhaler, or ask her nurse or pharmacist.","zh":"不一定。吸入器的用法不一樣，很多乾粉吸入器不能搖。她要照自己那一支的說明用，或問她的護理師、藥師。"},{"who":"Nurse Bennett","en":"Now, can you show me how you'll use it? That way I know I explained it clearly.","zh":"現在可以做一次給我看嗎？這樣我才知道我有沒有說清楚。"}],"questions":[{"q":"What should Mr. Murphy do first?","options":["Shake it and take off the cap","Hold his breath","Press it twice"],"answer":0},{"q":"How long should he hold his breath?","options":["One minute","Ten seconds","Two seconds"],"answer":1},{"q":"Why does the nurse ask him to show her?","options":["She wants to take a photo","To check that she explained it clearly","She forgot the steps"],"answer":1}],"words":[{"en":"inhaler","zh":"吸入器"},{"en":"shake","zh":"搖"},{"en":"cap","zh":"蓋子"},{"en":"puff","zh":"（噴劑）一下"},{"en":"hold your breath","zh":"憋氣"},{"en":"metered-dose inhaler","zh":"定量噴霧吸入器（MDI）"}]},{"id":"nl-28","title":"A Child With a Fever","scene":"媽媽擔心孩子發燒：說明藥量看體重、補水、別蓋太多","level":"B1","accent":"en-AU","you":"Nurse Ryan","emma":"Mrs. Lin","dialogue":[{"who":"Mrs. Lin","en":"My son's temperature is thirty-nine. Is that very bad?","zh":"我兒子體溫 39 度，很嚴重嗎？"},{"who":"Nurse Ryan","en":"I understand you're worried. A fever helps his body fight the infection, and we'll keep a close eye on him.","zh":"我了解你很擔心。發燒是身體在對抗感染，我們會密切觀察他。"},{"who":"Mrs. Lin","en":"Can you give him some medicine?","zh":"可以給他藥嗎？"},{"who":"Nurse Ryan","en":"Yes. The doctor has ordered paracetamol for him. For children, the dose depends on their weight, so I'll check it carefully before I give it.","zh":"可以。醫師有開 paracetamol。小孩的劑量看體重，所以給之前我會仔細核對。"},{"who":"Mrs. Lin","en":"He doesn't want to drink anything.","zh":"他什麼都不想喝。"},{"who":"Nurse Ryan","en":"Try small sips often, maybe an icy pole or some diluted juice. Kids lose more fluid when they have a fever.","zh":"試試少量多次，可以給冰棒或稀釋的果汁。小孩發燒時會流失比較多水分。"},{"who":"Mrs. Lin","en":"Should I cover him with lots of blankets?","zh":"我要幫他蓋很多被子嗎？"},{"who":"Nurse Ryan","en":"No, light clothes and one thin blanket are better. Too many blankets can make the fever go higher.","zh":"不用，穿輕薄的衣服、蓋一條薄被比較好。蓋太多會讓體溫更高。"},{"who":"Mrs. Lin","en":"OK. When should I worry?","zh":"好。什麼時候該擔心？"},{"who":"Nurse Ryan","en":"Press the call button if he's very sleepy and hard to wake, has trouble breathing, or gets a rash.","zh":"如果他很嗜睡、很難叫醒、呼吸困難或出疹子，就按呼叫鈴。"},{"who":"Mrs. Lin","en":"Thank you. That helps a lot.","zh":"謝謝，幫了很大的忙。"}],"questions":[{"q":"What decides a child's medicine dose?","options":["His age only","His height","His weight"],"answer":2},{"q":"What does the nurse say about blankets?","options":["Use many blankets","Use no clothes at all","Use light clothes and one thin blanket"],"answer":2},{"q":"When should Mrs. Lin press the call button?","options":["When he is very sleepy and hard to wake","When he wants to watch TV","When he asks for juice"],"answer":0}],"words":[{"en":"fever","zh":"發燒"},{"en":"dose","zh":"劑量"},{"en":"weight","zh":"體重"},{"en":"sip","zh":"小口喝"},{"en":"diluted","zh":"稀釋的"}]},{"id":"nl-29","title":"Asking for More Pain Medicine","scene":"病人提早要止痛藥：重新評估疼痛、通知醫師、先冰敷","level":"B1","accent":"en-US","you":"Nurse Shah","emma":"Mr. Rogers","dialogue":[{"who":"Mr. Rogers","en":"Nurse, can I have more pain medicine? It really hurts.","zh":"護理師，可以再給我止痛藥嗎？真的好痛。"},{"who":"Nurse Shah","en":"I'm sorry you're hurting. Your last dose was at two o'clock, and the next one can be given at six.","zh":"很抱歉你在痛。你上一劑是兩點，下一劑六點才能給。"},{"who":"Mr. Rogers","en":"It's only four thirty!","zh":"現在才四點半！"},{"who":"Nurse Shah","en":"I know. Let me check you first. What number is your pain, from zero to ten?","zh":"我知道。我先評估一下，痛從 0 到 10 幾分？"},{"who":"Mr. Rogers","en":"Eight. It was a four after the medicine.","zh":"8 分。吃完藥後是 4 分。"},{"who":"Nurse Shah","en":"That's a big change. Did something happen? Did you move or get up?","zh":"變化很大。有發生什麼事嗎？有動到或起身嗎？"},{"who":"Mr. Rogers","en":"I walked to the bathroom.","zh":"我走去廁所。"},{"who":"Nurse Shah","en":"OK. I'll call your doctor, because the medicine may not be strong enough for you.","zh":"好。我會打給醫師，因為這個藥對你可能不夠強。"},{"who":"Mr. Rogers","en":"Thank you.","zh":"謝謝。"},{"who":"Nurse Shah","en":"While we wait, I can put an ice pack on your knee and help you find a better position.","zh":"等的時候，我可以幫你膝蓋冰敷，再幫你調一個比較好的姿勢。"},{"who":"Mr. Rogers","en":"The ice sounds good.","zh":"冰敷聽起來不錯。"}],"questions":[{"q":"When can the next dose be given?","options":["At four thirty","At six o'clock","At two o'clock"],"answer":1},{"q":"What was his pain score after the last medicine?","options":["Eight","Four","Zero"],"answer":1},{"q":"What will the nurse do?","options":["Give him two doses","Call his doctor and offer an ice pack","Tell him to wait quietly"],"answer":1}],"words":[{"en":"dose","zh":"一劑"},{"en":"pain score","zh":"疼痛分數"},{"en":"strong enough","zh":"夠強"},{"en":"ice pack","zh":"冰敷袋"},{"en":"position","zh":"姿勢"}]},{"id":"nl-30","title":"First Day on the Unit","scene":"實習第一天：臨床指導帶你認識病房","level":"A2","accent":"en-US","you":"Wei","emma":"Nurse Rivera","dialogue":[{"who":"Nurse Rivera","en":"Hi! You must be the new student. I'm Carmen, and I'll be your preceptor today.","zh":"嗨！你一定是新來的學生。我是 Carmen，今天是你的臨床指導。"},{"who":"Wei","en":"Hi, Carmen. I'm Wei. Nice to meet you.","zh":"嗨 Carmen，我是 Wei，很高興認識你。"},{"who":"Nurse Rivera","en":"Nice to meet you too. Let me show you around. This is the nurses' station.","zh":"我也很高興認識你。我帶你到處看看，這裡是護理站。"},{"who":"Wei","en":"Where do you keep the medicines?","zh":"藥放在哪裡？"},{"who":"Nurse Rivera","en":"In the medication room, behind that door. You need your badge to open it.","zh":"在給藥室，那扇門後面，要用識別證才打得開。"},{"who":"Wei","en":"OK. And where are the gloves?","zh":"好。手套在哪裡？"},{"who":"Nurse Rivera","en":"There are gloves in every room, next to the sink.","zh":"每間病房都有手套，在洗手台旁邊。"},{"who":"Wei","en":"What will I do today?","zh":"我今天要做什麼？"},{"who":"Nurse Rivera","en":"Today you'll follow me with two patients. You can take their vital signs and help with breakfast.","zh":"今天你跟著我照顧兩位病人，可以幫忙量生命徵象、幫忙早餐。"},{"who":"Wei","en":"I'm a little nervous.","zh":"我有點緊張。"},{"who":"Nurse Rivera","en":"That's normal. Ask me anything. There are no stupid questions here.","zh":"很正常。什麼都可以問我，這裡沒有笨問題。"}],"questions":[{"q":"Who is Carmen?","options":["A doctor","The student's preceptor","A patient"],"answer":1},{"q":"What does Wei need to open the medication room?","options":["A key","A password","His badge"],"answer":2},{"q":"What will Wei do today?","options":["Give medicines alone","Take vital signs and help with breakfast","Go home early"],"answer":1}],"words":[{"en":"preceptor","zh":"臨床指導"},{"en":"nurses' station","zh":"護理站"},{"en":"medication room","zh":"給藥室"},{"en":"badge","zh":"識別證"},{"en":"sink","zh":"洗手台"}]}]`);export{e as default};
